// ============================================================================
// POO UNIFICADA EN NODO CODE: Herencia de 3 niveles y Polimorfismo Real (Retos 1 y 3)
// ============================================================================

/**
 * Clase Abuelo: EntidadComercial
 * Representa la entidad base comercial (persona física o jurídica).
 */
class EntidadComercial {
  /**
   * @param {string} nombre - Nombre o razón social
   * @param {string} cedula - Número de identificación o cédula jurídica/física
   * @param {string} correo - Correo electrónico de contacto o notificación (Reto 3)
   * @param {string} email - Alias de compatibilidad para correo
   */
  constructor(nombre, cedula, correo = '', email = '') {
    this.nombre = nombre || '';
    this.cedula = cedula || '';
    this.correo = correo || email || '';
    this.email = this.correo;
  }

  /**
   * Formatea y valida la identidad básica de cualquier persona o empresa registrada.
   * @returns {string} Identificación formateada
   */
  obtenerIdentificacion() {
    if (!this.cedula || !this.cedula.trim()) {
      return `${this.nombre || 'Entidad sin nombre'} [SIN CÉDULA REGISTRADA]`;
    }
    const correoInfo = this.email ? ` <${this.email}>` : '';
    return `${this.nombre} (ID: ${this.cedula.trim()})${correoInfo}`;
  }

  /**
   * Valida si la entidad cuenta con una cédula válida no vacía
   * @returns {boolean}
   */
  esIdentificacionValida() {
    return Boolean(this.cedula && this.cedula.toString().trim().length > 0);
  }
}

 EntidadComercial;

/**
 * Clase Padre: Proveedor
 * Hereda de EntidadComercial e incorpora el estado ante Hacienda y la evaluación de riesgo financiero.
 */
class Proveedor extends EntidadComercial {
  /**
   * @param {string} nombre - Nombre del proveedor
   * @param {string} cedula - Cédula tributaria del proveedor
   * @param {string|null} estadoHacienda - Estado tributario ("Al dia", "Moroso", "Desconocido")
   * @param {string|null} nivelRiesgo - Nivel de riesgo asignado ("Bajo", "Alto", etc.)
   * @param {string} correo - Correo electrónico del proveedor (Reto 3)
   * @param {string} email - Alias de compatibilidad
   */
  constructor(nombre, cedula, estadoHacienda = null, nivelRiesgo = null, correo = '', email = '') {
    super(nombre, cedula, correo, email);
    this.estadoHacienda = estadoHacienda;
    this.nivelRiesgo = nivelRiesgo;
  }

  /**
   * Reto 1 - Método Base Polimórfico: procesarPagoEspecifico
   * Define la firma para el cálculo polimórfico del monto final según el tipo de proveedor.
   * Las subclases (ProveedorServicios y ProveedorBienes) deben sobrescribir este método.
   * @param {number} montoBase - Monto bruto original
   * @returns {{ montoBase: number, montoFinal: number, conceptoAjuste: string }}
   */
  procesarPagoEspecifico(montoBase) {
    throw new Error('El método procesarPagoEspecifico(montoBase) debe ser implementado por la subclase especializada.');
  }

  /**
   * Genera una Clave de Pago única y legible para trazabilidad y comprobantes.
   * Formato: REF-[AÑO]-PAY-[ID]-[RANDOM] (Ej: REF-2026-PAY-PAG-001-A8F2)
   * @param {string} idPago - Identificador del pago
   * @param {string} fecha - Fecha del pago
   * @returns {string} Clave de pago alfanumérica única
   */
  generarClavePago(idPago = '000', fecha = new Date().toISOString().split('T')[0]) {
    const anio = fecha ? (new Date(fecha).getFullYear() || 2026) : 2026;
    const randomHex = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `REF-${anio}-PAY-${idPago}-${randomHex}`;
  }

  /**
   * Genera la cadena de texto estandarizada (inmutable) para codificar en el código QR.
   * @param {number} montoFinal - Monto final liquidado tras polimorfismo
   * @param {string} clavePago - Clave única de referencia
   * @param {string} fecha - Fecha de la transacción
   * @param {string} detalle - Descripción o detalle de la categoría
   * @returns {string} Payload inmutable para el QR
   */
  generarPayloadQR(montoFinal, clavePago, fecha = new Date().toISOString().split('T')[0], detalle = '') {
    const ref = clavePago || this.generarClavePago('000', fecha);
    const desc = detalle || 'Transacción Comercial';
    return `CLAVE: ${ref} | PROVEEDOR: ${this.nombre} | CEDULA: ${this.cedula} | MONTO_NETO: CRC ${Number(montoFinal).toFixed(2)} | FECHA: ${fecha} | CONCEPTO: ${desc}`;
  }

  /**
   * Evalúa el riesgo financiero del proveedor según su estado ante Hacienda.
   * Aplica RN-01 (Validación obligatoria), RN-02 (Bloqueo por morosidad) y ERR-02 (Servicio caído / Desconocido).
   * @returns {{ esRiesgoso: boolean, nivelRiesgo: string, motivo: string }}
   */
  evaluarRiesgo() {
    // ERR-02: Caída de servicio externo o cédula no encontrada en Hacienda
    if (this.estadoHacienda === 'Desconocido') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Error de conexión con Hacienda - Revisión manual'
      };
    }

    // RN-01: Validación tributaria obligatoria
    if (!this.estadoHacienda || this.estadoHacienda.trim() === '') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Validación tributaria obligatoria pendiente ante Hacienda'
      };
    }

    // RN-02: Bloqueo automático por morosidad
    const estadoNormalizado = this.estadoHacienda.trim().toLowerCase();
    if (estadoNormalizado === 'moroso') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Proveedor figura como Moroso ante el Ministerio de Hacienda'
      };
    }

    if (estadoNormalizado === 'al dia' || estadoNormalizado === 'al día') {
      this.nivelRiesgo = 'Bajo';
      return {
        esRiesgoso: false,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Proveedor al día con obligaciones tributarias'
      };
    }

    // Cualquier otro estado desconocido o no reconocido
    this.nivelRiesgo = 'Alto';
    return {
      esRiesgoso: true,
      nivelRiesgo: this.nivelRiesgo,
      motivo: `Estado tributario no concluyente (${this.estadoHacienda}) - Requiere revisión manual`
    };
  }
}

 Proveedor;

/**
 * Clase Hija: ProveedorServicios
 * Reto 1: Herencia de Proveedor y aplicación de Polimorfismo.
 * Especializada en proveedores de la categoría "Servicios" (ej. TI, consultoría, soporte).
 * Sobrescribe procesarPagoEspecifico() deduciendo un 2% de retención fiscal al monto base.
 */
class ProveedorServicios extends Proveedor {
  /**
   * @param {string} nombre - Nombre del proveedor
   * @param {string} cedula - Cédula tributaria
   * @param {string|null} estadoHacienda - Estado tributario ante Hacienda
   * @param {string|null} nivelRiesgo - Nivel de riesgo
   * @param {string} detalle_categoria - Detalle o especialidad (ej. "TI", "Consultoría")
   * @param {number} porcentajeRetencion - Porcentaje de retención (por defecto 2% según Reto 1)
   * @param {string} correo - Correo electrónico de contacto o notificación (Reto 3)
   * @param {string} email - Alias de compatibilidad
   */
  constructor(
    nombre,
    cedula,
    estadoHacienda = null,
    nivelRiesgo = null,
    detalle_categoria = 'TI',
    porcentajeRetencion = 2,
    correo = '',
    email = ''
  ) {
    super(nombre, cedula, estadoHacienda, nivelRiesgo, correo, email);
    this.categoria = 'Servicios';
    this.detalle_categoria = detalle_categoria || 'Servicios Profesionales';
    this.tipoServicio = this.detalle_categoria; // Compatibilidad
    this.porcentajeRetencion = typeof porcentajeRetencion === 'number' ? porcentajeRetencion : 2;
  }

  /**
   * Reto 1 - Polimorfismo: procesarPagoEspecifico
   * Sobrescribe el método de la clase padre Proveedor.
   * Resta un 2% de retención de impuestos al monto base.
   * @param {number} montoBase - Monto bruto antes de deducciones
   * @returns {{ montoBase: number, categoria: string, detalle_categoria: string, porcentajeRetencion: number, retencion: number, flete: number, montoFinal: number, conceptoAjuste: string }}
   */
  procesarPagoEspecifico(montoBase) {
    const bruto = Number(montoBase) || 0;
    const factor = this.porcentajeRetencion > 1 ? this.porcentajeRetencion / 100 : this.porcentajeRetencion;
    const retencion = Number((bruto * factor).toFixed(2));
    const montoFinal = Number((bruto - retencion).toFixed(2));

    return {
      montoBase: bruto,
      categoria: this.categoria,
      detalle_categoria: this.detalle_categoria,
      porcentajeRetencion: this.porcentajeRetencion,
      retencion,
      flete: 0,
      montoFinal,
      montoNeto: montoFinal,
      conceptoAjuste: `Retención fiscal (${this.porcentajeRetencion}%)`
    };
  }

  /**
   * Alias de compatibilidad con código previo
   * @param {number} montoBruto
   */
  calcularMontoNeto(montoBruto) {
    const res = this.procesarPagoEspecifico(montoBruto);
    return {
      montoBruto: res.montoBase,
      porcentajeRetencion: res.porcentajeRetencion,
      montoRetencion: res.retencion,
      montoNeto: res.montoFinal
    };
  }

  /**
   * Genera simultáneamente la clave de pago y el payload del código QR.
   * @param {string} idPago - Identificador del pago
   * @param {number} montoNeto - Monto final liquidado
   * @param {string} fecha - Fecha del pago
   * @returns {{ clavePago: string, datosParaQR: string }}
   */
  generarComprobante(idPago, montoNeto, fecha = new Date().toISOString().split('T')[0]) {
    const clavePago = this.generarClavePago(idPago, fecha);
    const datosParaQR = this.generarPayloadQR(montoNeto, clavePago, fecha, this.detalle_categoria);
    return {
      clavePago,
      datosParaQR
    };
  }
}

 ProveedorServicios;

/**
 * Clase Hija: ProveedorBienes
 * Reto 1: Herencia de Proveedor y aplicación de Polimorfismo.
 * Especializada en proveedores de la categoría "Bienes" (ej. suministros, mobiliario, hardware).
 * Sobrescribe procesarPagoEspecifico() sumando un monto fijo de flete (ej. CRC 5000) al monto base.
 */
class ProveedorBienes extends Proveedor {
  /**
   * @param {string} nombre - Nombre del proveedor
   * @param {string} cedula - Cédula tributaria
   * @param {string|null} estadoHacienda - Estado tributario ante Hacienda
   * @param {string|null} nivelRiesgo - Nivel de riesgo
   * @param {string} detalle_categoria - Detalle o especialidad (ej. "Suministros de oficina", "Hardware")
   * @param {number} flete - Monto fijo de flete o transporte (por defecto CRC 5000 según Reto 1)
   * @param {string} correo - Correo electrónico de contacto o notificación (Reto 3)
   * @param {string} email - Alias de compatibilidad
   */
  constructor(
    nombre,
    cedula,
    estadoHacienda = null,
    nivelRiesgo = null,
    detalle_categoria = 'Suministros de oficina',
    flete = 5000,
    correo = '',
    email = ''
  ) {
    super(nombre, cedula, estadoHacienda, nivelRiesgo, correo, email);
    this.categoria = 'Bienes';
    this.detalle_categoria = detalle_categoria || 'Suministros de oficina';
    this.flete = typeof flete === 'number' ? flete : 5000;
  }

  /**
   * Reto 1 - Polimorfismo: procesarPagoEspecifico
   * Sobrescribe el método de la clase padre Proveedor.
   * Suma un monto fijo de flete (ej. 5000) al monto base.
   * @param {number} montoBase - Monto bruto original
   * @returns {{ montoBase: number, categoria: string, detalle_categoria: string, porcentajeRetencion: number, retencion: number, flete: number, montoFinal: number, conceptoAjuste: string }}
   */
  procesarPagoEspecifico(montoBase) {
    const bruto = Number(montoBase) || 0;
    const fleteMonto = Number(this.flete) || 5000;
    const montoFinal = Number((bruto + fleteMonto).toFixed(2));

    return {
      montoBase: bruto,
      categoria: this.categoria,
      detalle_categoria: this.detalle_categoria,
      porcentajeRetencion: 0,
      retencion: 0,
      flete: fleteMonto,
      montoFinal,
      montoNeto: montoFinal,
      conceptoAjuste: `Flete y transporte (+CRC ${fleteMonto.toLocaleString('es-CR')})`
    };
  }

  /**
   * Alias de cálculo para mantener consistencia con interfaces de pago
   * @param {number} montoBruto
   */
  calcularMontoNeto(montoBruto) {
    const res = this.procesarPagoEspecifico(montoBruto);
    return {
      montoBruto: res.montoBase,
      porcentajeRetencion: 0,
      montoRetencion: 0,
      flete: res.flete,
      montoNeto: res.montoFinal
    };
  }

  /**
   * Genera simultáneamente la clave de pago y el payload del código QR.
   * @param {string} idPago - Identificador del pago
   * @param {number} montoNeto - Monto final liquidado
   * @param {string} fecha - Fecha del pago
   * @returns {{ clavePago: string, datosParaQR: string }}
   */
  generarComprobante(idPago, montoNeto, fecha = new Date().toISOString().split('T')[0]) {
    const clavePago = this.generarClavePago(idPago, fecha);
    const datosParaQR = this.generarPayloadQR(montoNeto, clavePago, fecha, this.detalle_categoria);
    return {
      clavePago,
      datosParaQR
    };
  }
}

 ProveedorBienes;

/**
 * Clase de Proceso / Composición: Pago
 * Contiene y orquesta el procesamiento del pago a un Proveedor (Servicios o Bienes),
 * aplicando polimorfismo con procesarPagoEspecifico(), emisión de Clave de Pago y QR.
 */
class Pago {
  /**
   * @param {string} idPago - Identificador único del pago (ej. "PAG-001")
   * @param {number} monto - Monto bruto original
   * @param {ProveedorServicios|ProveedorBienes} proveedor - Instancia de subclase de Proveedor (Composición)
   * @param {string} fecha - Fecha del pago (YYYY-MM-DD)
   * @param {string} estado - Estado inicial del pago ("Pendiente")
   */
  constructor(idPago, monto, proveedor, fecha = new Date().toISOString().split('T')[0], estado = 'Pendiente') {
    this.idPago = idPago;
    this.monto = Number(monto);
    this.proveedor = proveedor;
    this.fecha = fecha;
    this.estado = estado;
    this.estadoProcesado = estado;
    this.montoFinal = null;
    this.montoNeto = null;
    this.retencion = 0;
    this.flete = 0;
    this.calculoEspecifico = null;
    this.clavePago = null;
    this.datosParaCodificarEnQR = null;
    this.datosParaQR = null;
    this.qrUrl = null;
    this.correoDestino = proveedor ? (proveedor.correo || proveedor.email || '') : '';
    this.emailHtml = null;
    this.motivoRetencion = null;
  }

  /**
   * Genera la plantilla HTML premium y profesional del comprobante de pago para correo.
   * Interpola directamente los valores reales calculados mediante polimorfismo.
   * @returns {string} Plantilla HTML completamente renderizada
   */
  generarEmailHtml() {
    if (this.estado !== 'Aprobado') {
      return '';
    }

    const montoBrutoFmt = Number(this.monto).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const montoFinalFmt = Number(this.montoFinal).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const retencionFmt = Number(this.retencion).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fleteFmt = Number(this.flete).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    const categoria = this.proveedor ? this.proveedor.categoria : 'General';
    const detalleCategoria = this.proveedor ? (this.proveedor.detalle_categoria || this.proveedor.tipoServicio) : 'Comercial';

    // Fila dinámica de ajuste polimórfico (Retención para Servicios o Flete para Bienes)
    let filaAjusteHtml = '';
    if (this.retencion > 0) {
      filaAjusteHtml = `
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #e11d48; border-bottom: 1px solid #e2e8f0;">Retención Fiscal (${this.calculoEspecifico?.porcentajeRetencion || 2}%):</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #e11d48; text-align: right; border-bottom: 1px solid #e2e8f0;">- CRC ${retencionFmt}</td>
          </tr>`;
    } else if (this.flete > 0) {
      filaAjusteHtml = `
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #0284c7; border-bottom: 1px solid #e2e8f0;">Cargo por Flete y Transporte:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #0284c7; text-align: right; border-bottom: 1px solid #e2e8f0;">+ CRC ${fleteFmt}</td>
          </tr>`;
    }

    return `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Comprobante de Pago Aprobado</title>
</head>
<body style="margin: 0; padding: 24px 10px; background-color: #f1f5f9; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #1e293b;">

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center" style="max-width: 580px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);">

    <!-- ENCABEZADO ELEGANTE -->
    <tr>
      <td style="padding: 32px 28px 24px; background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%); text-align: center;">
        <div style="display: inline-block; padding: 6px 14px; background: rgba(16, 185, 129, 0.15); border: 1px solid #10b981; border-radius: 20px; margin-bottom: 12px;">
          <span style="color: #34d399; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase;">✔ PAGO APROBADO &amp; VERIFICADO</span>
        </div>
        <h1 style="margin: 0 0 6px 0; font-size: 24px; font-weight: 800; color: #ffffff; letter-spacing: -0.5px;">Comprobante Oficial de Pago</h1>
        <p style="margin: 0; font-size: 13px; color: #94a3b8;">Sistema de Liquidación y Panel de Riesgo con Código QR</p>
      </td>
    </tr>

    <!-- CONTENIDO DEL COMPROBANTE -->
    <tr>
      <td style="padding: 28px 28px 20px;">

        <p style="margin: 0 0 12px; font-size: 15px; color: #334155;">
          Estimado(a) <strong style="color: #0f172a;">${this.proveedor.nombre}</strong>,
        </p>
        <p style="margin: 0 0 20px; font-size: 13px; color: #64748b; line-height: 1.5;">
          Le confirmamos que su orden de pago ha sido aprobada y liquidada de conformidad con las disposiciones tributarias vigentes ante el Ministerio de Hacienda (Estado: <strong style="color: #059669;">Al día</strong>).
        </p>

        <!-- TARJETA CLAVE DE PAGO EN GRANDE -->
        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-left: 4px solid #0284c7; border-radius: 8px; padding: 18px 16px; text-align: center; margin: 20px 0;">
          <div style="font-size: 11px; font-weight: 800; color: #0284c7; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 6px;">
            🔑 CLAVE DE PAGO ÚNICA DE AUDITORÍA
          </div>
          <div style="font-size: 24px; font-weight: 900; font-family: 'Courier New', monospace; color: #0f172a; letter-spacing: 2px;">
            ${this.clavePago}
          </div>
          <div style="font-size: 11px; color: #64748b; margin-top: 4px;">Referencia inmutable de auditoría</div>
        </div>

        <!-- TABLA DE DETALLES Y RETENCIONES -->
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; margin: 20px 0; overflow: hidden;">
          <tr>
            <td colspan="2" style="padding: 12px 16px; background: #f8fafc; border-bottom: 1px solid #e2e8f0;">
              <strong style="font-size: 12px; color: #475569; text-transform: uppercase; letter-spacing: 0.8px;">Detalles de la Transacción</strong>
            </td>
          </tr>
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9;">ID del Pago:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #0f172a; text-align: right; border-bottom: 1px solid #f1f5f9;">${this.idPago}</td>
          </tr>
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9;">Identificación / Cédula:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #0f172a; text-align: right; border-bottom: 1px solid #f1f5f9;">${this.proveedor.cedula}</td>
          </tr>
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9;">Categoría del Proveedor:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #0f172a; text-align: right; border-bottom: 1px solid #f1f5f9;">${categoria} (${detalleCategoria})</td>
          </tr>
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9;">Fecha de Aplicación:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #0f172a; text-align: right; border-bottom: 1px solid #f1f5f9;">${this.fecha}</td>
          </tr>
          <tr>
            <td style="padding: 10px 16px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9;">Monto Base:</td>
            <td style="padding: 10px 16px; font-size: 13px; font-weight: 600; color: #334155; text-align: right; border-bottom: 1px solid #f1f5f9;">CRC ${montoBrutoFmt}</td>
          </tr>
          ${filaAjusteHtml}
          <tr style="background: #f0fdf4;">
            <td style="padding: 14px 16px; font-size: 14px; font-weight: 700; color: #166534;">Monto Final Liquidado:</td>
